#!/usr/bin/env python3
"""Summarize a regenerated verification-metadata.xml for human review.

Prints Markdown. Exits non-zero when the change cannot come from a plain
regeneration: weakened settings, or existing entries that changed.
"""
import re
import sys
import xml.etree.ElementTree as ET

NS = "{https://schema.gradle.org/dependency-verification}"
SETTINGS = ("verify-metadata", "verify-signatures", "keyring-format", "key-servers", "trusted-artifacts")


def settings(root):
    configuration = root.find(f"{NS}configuration")
    return {
        name: ET.tostring(element, encoding="unicode").strip() if element is not None else None
        for name in SETTINGS
        for element in [configuration.find(f"{NS}{name}")]
    }


def scope(attributes):
    keys = ("group", "name", "version", "file")
    text = ":".join(attributes[key] for key in keys if key in attributes) or "(all)"
    return f"{text} (regex)" if attributes.get("regex") == "true" else text


def trusted_keys(root):
    result = set()
    for key in root.iter(f"{NS}trusted-key"):
        trusting = key.findall(f"{NS}trusting")
        for attributes in [element.attrib for element in trusting] or [key.attrib]:
            result.add((key.get("id"), scope(attributes)))
    return result


def ignored_keys(root):
    return {(key.get("id"), key.get("reason", "")) for key in root.iter(f"{NS}ignored-key")}


def checksums(root):
    """Map (component, artifact, kind) to its accepted values and generation reason."""
    result = {}
    for component in root.iter(f"{NS}component"):
        coordinates = ":".join(component.get(key) for key in ("group", "name", "version"))
        for artifact in component.findall(f"{NS}artifact"):
            for entry in artifact:
                kind = entry.tag.removeprefix(NS)
                if kind == "ignored-keys":
                    continue
                values = [entry.get("value")]
                values += [also.get("value") for also in entry.findall(f"{NS}also-trust")]
                result[(coordinates, artifact.get("name"), kind)] = (values, entry.get("reason"))
    return result


def key_owners(keyring):
    owners = {}
    key_id = None
    for line in open(keyring, encoding="utf-8"):
        if match := re.match(r"pub\s+(\S+)", line):
            key_id = match[1]
        elif (match := re.match(r"uid\s+(.+)", line)) and key_id:
            owners.setdefault(key_id, match[1].strip())
    return owners


def is_signed_group(group, keys):
    for _, key_scope in keys:
        pattern, _, _ = key_scope.removesuffix(" (regex)").partition(":")
        if group == pattern or (key_scope.endswith(" (regex)") and re.fullmatch(pattern, group)):
            return True
    return False


def main(old_path, new_path, keyring_path):
    old, new = ET.parse(old_path).getroot(), ET.parse(new_path).getroot()
    problems = []

    for name, value in settings(old).items():
        if settings(new)[name] != value:
            problems.append(f"Setting `{name}` changed")

    old_checksums, new_checksums = checksums(old), checksums(new)
    for key, (values, _) in old_checksums.items():
        if key not in new_checksums:
            problems.append(f"Entry removed: `{' '.join(key)}`")
        elif not set(new_checksums[key][0]) <= set(values):
            problems.append(f"Accepted values changed: `{' '.join(key)}`")

    for key_id, reason in sorted(ignored_keys(new) - ignored_keys(old)):
        if reason == "PGP verification failed":
            problems.append(f"Signature verification failed with trusted key `{key_id}`")

    new_keys = sorted(trusted_keys(new) - trusted_keys(old))
    owners = key_owners(keyring_path)
    added = sorted(key for key in new_checksums if key not in old_checksums)
    ignored = sorted(ignored_keys(new) - ignored_keys(old))
    old_trusted = trusted_keys(old)

    print("## Regenerated verification metadata\n")
    print("Generated by running the updated build without verification. Review before merging.\n")
    if problems:
        print("### Rejected\n")
        print("\n".join(f"- {problem}" for problem in problems), "\n")

    print(f"### Trust granted to keys ({len(new_keys)})\n")
    print("Confirm each fingerprint and scope with the publisher. The owner is the unauthenticated key user ID.\n")
    for fingerprint, key_scope in new_keys:
        print(f"- `{fingerprint}` for `{key_scope}`: {owners.get(fingerprint[-16:], 'unknown owner')}")

    print(f"\n### Ignored keys ({len(ignored)})\n")
    for key_id, reason in ignored:
        print(f"- `{key_id}`: {reason}")

    print(f"\n### Artifacts accepted by hash or pinned key ({len(added)})\n")
    print("Trust on first use: nothing but this review vouches for these.\n")
    for key in added:
        coordinates, artifact, kind = key
        values, reason = new_checksums[key]
        warning = " [group has trusted keys: check for a dropped signature]" if is_signed_group(coordinates.split(":")[0], old_trusted) else ""
        print(f"- `{coordinates}` `{artifact}` {kind} `{values[0][:16]}` ({reason or 'no reason recorded'}){warning}")

    if problems:
        print("\n".join(f"::error::{problem}" for problem in problems), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(*sys.argv[1:]))
